        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos I.13</em> <small>(c. 350 AD)</small><p>&#x27;Who being the brightness of his glory, and the express image of his person, and upholding all things by the word of his power...&#x27; — Athanasius marks the triad apaugasma tēs doxēs + charaktēr tēs hypostaseōs + pherōn ta panta as the densest Christological cluster in the NT. The apaugasma (effulgence, radiance-from-the-source) names the Son&#x27;s eternal-procession-from-the-Father in the same metaphysical-mode as light-from-fire (the light is genuinely-from the fire and genuinely-of the same nature, not subordinate or temporally-later). The charaktēr tēs hypostaseōs (express-imprint of his person — the imprint that a coin shows from its die) names the perfect-ontological-imaging: the Son shows-forth precisely what the Father is. The pherōn ta panta tō rhēmati tēs dynameōs (upholding all-things by the word of his power) names the cosmic-sustaining-Christology. The Tewahedo Trisagion preserves all three Hebrews-anchor predications in its anti-Arian formula.</p></aside>',
