        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §10</em> <small>(c. 350 AD)</small><p>&#x27;Forasmuch then as the children are partakers of flesh and blood, he also himself likewise took part of the same; that through death he might destroy him that had the power of death, that is, the devil&#x27; — Athanasius marks paraplēsiōs meteschen tōn autōn (likewise partook of the same) as the Pauline-anti-Docetic Hebrews-anchor. The Word-incarnate did not merely-appear-flesh-and-blood but FULLY-PARTOOK-of (meteschen) the same-substance the children possess. The hina dia tou thanatou katargēsē (that through death he might destroy) names the soteriological-purpose: only by genuinely-dying could the Word destroy death-itself. Tewahedo Christmas + Holy-Friday lectionary pairs Heb 2:14 with Phil 2:7-8 as the genuine-participation-anchor.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
