        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Epistola ad Adelphium</em> <small>(c. 350 AD)</small><p>&#x27;For we have not an high priest which cannot be touched with the feeling of our infirmities; but was in all points tempted like as we are, yet without sin&#x27; — Athanasius marks pepeirasmenon kata panta kath&#x27; homoiotēta chōris hamartias (tempted in all-things according-to-likeness without sin) as the Hebrews-formal-statement of Christ&#x27;s-sinlessness-with-genuine-human-experience. The kata panta (in all-things) excludes Apollinarian-reduction (no human-aspect-missing); the kath&#x27; homoiotēta (according to likeness) excludes Docetic-non-genuineness; the chōris hamartias (without sin) excludes Adoptionist-or-Pelagian denial of Christ&#x27;s-moral-perfection. Tewahedo Holy-Friday meditation cites Heb 4:15 + Rom 8:3 (homoiōmati-sarkos) as the sinless-but-tempted Pauline-Hebrews-pair.</p></aside>',
        "Athanasius of Alexandria, Epistola ad Adelphium (Letter to Adelphius, Bishop and Confessor: Against the Arians), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD.",
