        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §9</em> <small>(c. 350 AD)</small><p>&#x27;How much more shall the blood of Christ, who through the eternal Spirit offered himself without spot to God, purge your conscience from dead works to serve the living God?&#x27; — Athanasius marks dia pneumatos aiōniou heauton prosēnenken amōmon tō theō (through eternal Spirit offered himself spotless to God) as the FULL-TRINITARIAN-atonement-structure: the Son offers (active-incarnational-priest) himself (object-of-offering = the incarnate-flesh) through the eternal-Spirit (the pneumatological-medium of the sacrifice) to the Father (recipient-of-the-acceptable-offering). All three Persons are active in the single-act of atonement. Tewahedo Anaphora consecration-prayer cites Heb 9:14 at the epiclesis-of-the-Spirit-upon-the-elements as the Trinitarian-eucharistic-pattern-anchor.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
